"use client";

import { useState } from "react";

/* ============================================================
   NeuroviaClientMap
   Mapa interactivo de Mexico (32 estados, geometria real via
   GeoJSON simplificado y proyectado a SVG) con las ciudades
   donde Neurovia Systems tiene proyectos en produccion.

   - Sin dependencias externas (no Mapbox / no Google Maps).
   - Click en un estado -> zoom + panel con clientes de ese estado.
   - Click en un pin -> tarjeta con el detalle de esa ciudad.
   - Los datos son estaticos (CLIENT_PINS): para actualizarlos,
     edita el arreglo mas abajo y vuelve a desplegar.
   ============================================================ */

