type CityPin = {
  id: string;
  city: string;
  state: string;
  x: number;
  y: number;
  base?: boolean;
  clients: ClientEntry[];
};
type StatePath = {
  name: string;
  d: string;
  bounds: [number, number, number, number];
  center: [number, number];
};

