const CLIENT_PINS: CityPin[] = [{"id": "vhsa", "city": "Villahermosa", "state": "Tabasco", "x": 710.8445340572584, "y": 441.20185882805845, "base": true, "clients": [{"name": "Cliente petrolero", "project": "Suite ERP · Mant. vehicular · Hidráulica (confidencial)"}, {"name": "Royers S.A. de C.V.", "project": "Sitio web corporativo"}, {"name": "Provalsa", "project": "Sitio web + catálogo industrial"}, {"name": "Emasur", "project": "Sistema a medida"}, {"name": "SOTOP (Gob. Tabasco)", "project": "Sistema web de dictamen"}, {"name": "Huella", "project": "Producto propio · software veterinario"}, {"name": "Neurovía SGI", "project": "Producto propio · gestión integral"}, {"name": "Tomín POS", "project": "Producto propio · SaaS multi-tenant"}]}, {"id": "mty", "city": "Monterrey", "state": "Nuevo León", "x": 510.57476858509, "y": 221.085159622735, "base": false, "clients": [{"name": "Alpha Mobil", "project": "Sitio web + catálogo (mobiliario corporativo)"}, {"name": "TACEF Group", "project": "Sitio web corporativo (San Pedro Garza García, N.L.)"}]}, {"id": "gdl", "city": "Guadalajara", "state": "Jalisco", "x": 428.1278541698929, "y": 364.8412021887975, "base": false, "clients": [{"name": "Huella", "project": "Prospección clínicas veterinarias"}]}];

export default function NeuroviaClientMap() {
  const [activeState, setActiveState] = useState<string | null>(null);
  const [openCardId, setOpenCardId] = useState<string | null>(null);

  const totalClients = CLIENT_PINS.reduce((a, p) => a + p.clients.length, 0);
  const totalStates = new Set(CLIENT_PINS.map((p) => p.state)).size;

  function onStateClick(name: string) {
    setOpenCardId(null);
    setActiveState((prev) => (prev === name ? null : name));
  }

  const activeStateData = activeState
    ? STATE_PATHS.find((s) => s.name === activeState)
    : null;

  let transform = "";
  if (activeStateData) {
    const [bx0, by0, bx1, by1] = activeStateData.bounds;
    const bw = Math.max(bx1 - bx0, 40);
    const bh = Math.max(by1 - by0, 30);
    const padFactor = 1.6;
    const scale = Math.min(
      VIEW_W / (bw * padFactor),
      VIEW_H / (bh * padFactor),
      6
    );
    const cx = (bx0 + bx1) / 2;
    const cy = (by0 + by1) / 2;
    const tx = VIEW_W / 2 - cx * scale;
    const ty = VIEW_H / 2 - cy * scale;
    transform = `translate(${tx}px,${ty}px) scale(${scale})`;
  }

  const openPin = openCardId
    ? CLIENT_PINS.find((p) => p.id === openCardId)
    : null;

  const cityPinsInActiveState = activeState
    ? CLIENT_PINS.filter((p) => p.state === activeState)
    : [];

  return (
    <div className="nv-wrap">
      <style>{CSS}</style>

      <div className="nv-stats">
        <div className="nv-stat">
          <b>{totalClients}</b>
          <span>Clientes / proyectos</span>
        </div>
        <div className="nv-stat">
          <b>{CLIENT_PINS.length}</b>
          <span>Ciudades</span>
        </div>
        <div className="nv-stat">
          <b>{totalStates}</b>
          <span>Estados</span>
        </div>
      </div>

      <div className="nv-mapcard">
        <div className="nv-mapframe">
          <svg
            className="nv-mapsvg"
            viewBox={`0 0 ${VIEW_W} ${VIEW_H}`}
            preserveAspectRatio="xMidYMid meet"
          >
            <g style={{ transform, transition: "transform .55s cubic-bezier(.2,.8,.2,1)" }}>
              {STATE_PATHS.map((p) => (
                <path
                  key={p.name}
                  className={
                    "nv-state" + (activeState === p.name ? " nv-state-active" : "")
                  }
                  d={p.d}
                  onClick={() => onStateClick(p.name)}
                >
                  <title>{p.name}</title>
                </path>
              ))}
            </g>
          </svg>

          <div
            className="nv-pin-layer"
            style={{ transform, transformOrigin: "0 0", transition: "transform .55s cubic-bezier(.2,.8,.2,1)" }}
          >
            {CLIENT_PINS.map((p, i) => (
              <div
                key={p.id}
                className={"nv-pin" + (p.base ? " nv-pin-base" : "")}
                data-idx={i % 4}
                style={{ left: `${(p.x / VIEW_W) * 100}%`, top: `${(p.y / VIEW_H) * 100}%` }}
                onClick={(e) => {
                  e.stopPropagation();
                  setOpenCardId((prev) => (prev === p.id ? null : p.id));
                }}
              >
                <div className="nv-ring" />
                <div className="nv-dot" />
                <div className="nv-taglabel">
                  {p.city}
                  <span className="nv-count-badge">{p.clients.length}</span>
                </div>
              </div>
            ))}

            {openPin && (
              <div
                className="nv-card"
                style={{
                  left:
                    openPin.x > 620
                      ? `calc(${(openPin.x / VIEW_W) * 100}% - 224px)`
                      : `calc(${(openPin.x / VIEW_W) * 100}% + 20px)`,
                  top:
                    openPin.y > 380
                      ? `calc(${(openPin.y / VIEW_H) * 100}% - ${20 + openPin.clients.length * 30}px)`
                      : `calc(${(openPin.y / VIEW_H) * 100}% - 6px)`,
                }}
                onClick={(e) => e.stopPropagation()}
              >
                <button className="nv-close" onClick={() => setOpenCardId(null)}>
                  &#10005;
                </button>
                <h3>
                  {openPin.city}{" "}
                  <span className="nv-count-inline">({openPin.clients.length})</span>
                </h3>
                <div className="nv-state-name">
                  {openPin.state}
                  {openPin.base ? " \u00b7 Base de operaciones" : ""}
                </div>
                {openPin.clients.map((c, idx) => (
                  <div className="nv-client-row" key={idx}>
                    <b>{c.name}</b>
                    <span>{c.project}</span>
                  </div>
                ))}
              </div>
            )}
          </div>

          {activeState && (
            <div className="nv-state-panel" onClick={(e) => e.stopPropagation()}>
              <button className="nv-backbtn" onClick={() => setActiveState(null)}>
                &larr; Volver al mapa
              </button>
              <h3>{activeState}</h3>
              <div className="nv-count">
                {cityPinsInActiveState.reduce((a, p) => a + p.clients.length, 0)}{" "}
                clientes &middot; {cityPinsInActiveState.length} ciudad
                {cityPinsInActiveState.length === 1 ? "" : "es"}
              </div>
              {cityPinsInActiveState.length ? (
                cityPinsInActiveState.map((p) => (
                  <div className="nv-city-block" key={p.id}>
                    <div className="nv-cname">
                      {p.city}
                      {p.base ? " \u00b7 BASE" : ""}
                    </div>
                    {p.clients.map((c, idx) => (
                      <div className="nv-client-row" key={idx}>
                        <b>{c.name}</b>
                        <span>{c.project}</span>
                      </div>
                    ))}
                  </div>
                ))
              ) : (
                <div className="nv-empty">
                  Todav&iacute;a no tenemos proyectos aqu&iacute;.
                </div>
              )}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

const CSS = `
.nv-wrap{
  /* Brand-cohesive dark palette: petrol + warm gold (matches --accent #284a5e),
     not the original cold cyan/navy, so the map sings in tune with the site. */
  --nv-bg-deep:#0f2a44;
  --nv-bg-panel:#143552ee;
  --nv-state-fill:#1a3b5c;
  --nv-state-fill-hover:#224a75;
  --nv-state-fill-active:#2f6aa8;
  --nv-state-stroke:#2c5578;
  --nv-accent:#9ad6f7;
  --nv-accent-dim:#9ad6f755;
  --nv-accent2:#ffffff;
  --nv-text-primary:#eef6fd;
  --nv-text-muted:#9fb6cc;
  --nv-border-soft:#2a4d70;
  position:relative;
  font-family:'Inter',system-ui,sans-serif;
  color:var(--nv-text-primary);
  max-width:1100px;
  margin:0 auto;
}
.nv-stats{ display:flex; gap:10px; margin:0 0 16px; flex-wrap:wrap; }
.nv-stat{
  background:var(--nv-bg-panel); border:1px solid var(--nv-border-soft); border-radius:12px;
  padding:10px 16px; font-family:'JetBrains Mono',monospace;
  display:flex; flex-direction:column; gap:2px; min-width:120px;
}
.nv-stat b{ font-size:20px; font-weight:600; color:var(--nv-text-primary); }
.nv-stat span{ font-size:10px; color:var(--nv-text-muted); text-transform:uppercase; letter-spacing:.08em; }
.nv-mapcard{
  position:relative; border-radius:20px; border:1px solid var(--nv-border-soft);
  background:linear-gradient(180deg,#0b1230,#070b1f); padding:10px; overflow:hidden;
}
.nv-mapframe{ position:relative; width:100%; aspect-ratio:900/560; }
.nv-mapsvg{ position:absolute; inset:0; width:100%; height:100%; display:block; }
.nv-state{
  fill:var(--nv-state-fill); stroke:var(--nv-state-stroke); stroke-width:1;
  cursor:pointer; transition:fill .2s ease, stroke .2s ease;
}
.nv-state:hover{ fill:var(--nv-state-fill-hover); stroke:var(--nv-accent); }
.nv-state-active{ fill:var(--nv-state-fill-active); stroke:var(--nv-accent); stroke-width:1.4; }
.nv-pin-layer{ position:absolute; inset:0; }
.nv-pin{ position:absolute; transform:translate(-50%,-50%); cursor:pointer; z-index:3; }
.nv-ring{
  position:absolute; left:50%; top:50%; width:34px; height:34px;
  transform:translate(-50%,-50%); border-radius:50%; border:1px solid var(--nv-accent);
  opacity:0; animation:nv-ping 2.4s ease-out infinite;
}
.nv-pin-base .nv-ring{ border-color:var(--nv-accent2); }
.nv-pin[data-idx="1"] .nv-ring{ animation-delay:.4s; }
.nv-pin[data-idx="2"] .nv-ring{ animation-delay:.8s; }
.nv-pin[data-idx="3"] .nv-ring{ animation-delay:1.2s; }
@keyframes nv-ping{
  0%{ width:8px; height:8px; opacity:.9; }
  100%{ width:38px; height:38px; opacity:0; }
}
.nv-dot{
  position:absolute; left:50%; top:50%; width:9px; height:9px; border-radius:50%;
  transform:translate(-50%,-50%); background:var(--nv-accent);
  box-shadow:0 0 10px 3px var(--nv-accent-dim);
}
.nv-pin-base .nv-dot{ background:var(--nv-accent2); box-shadow:0 0 10px 3px #ffffff55; }
.nv-taglabel{
  position:absolute; top:14px; left:50%; transform:translateX(-50%);
  font-family:'JetBrains Mono',monospace; font-size:9.5px; color:var(--nv-text-muted);
  white-space:nowrap; background:#05070fcc; padding:2px 6px; border-radius:5px;
  border:1px solid var(--nv-border-soft); display:flex; align-items:center; gap:5px;
  pointer-events:none;
}
.nv-count-badge{
  display:inline-flex; align-items:center; justify-content:center;
  min-width:14px; height:14px; padding:0 3px; border-radius:7px;
  background:var(--nv-accent); color:#03131a; font-weight:700; font-size:9px; line-height:1;
}
.nv-pin-base .nv-count-badge{ background:var(--nv-accent2); }
.nv-count-inline{ font-family:'JetBrains Mono',monospace; font-size:11px; color:var(--nv-accent); font-weight:500; }
.nv-card{
  position:absolute; z-index:5; width:210px; background:var(--nv-bg-panel);
  backdrop-filter:blur(6px); border:1px solid var(--nv-border-soft); border-radius:12px;
  padding:12px 14px; box-shadow:0 12px 30px -10px #000c;
}
.nv-card h3{ margin:0 0 2px; font-size:15px; font-weight:600; }
.nv-state-name{ font-size:10.5px; color:var(--nv-text-muted); margin-bottom:8px; }
.nv-client-row{
  display:flex; justify-content:space-between; align-items:baseline; gap:8px;
  font-size:12px; padding:6px 0; border-top:1px solid var(--nv-border-soft);
}
.nv-client-row:first-of-type{ border-top:none; }
.nv-client-row b{ color:var(--nv-text-primary); font-weight:600; }
.nv-client-row span{ color:var(--nv-text-muted); font-size:10.5px; text-align:right; }
.nv-close{
  position:absolute; top:8px; right:10px; cursor:pointer; color:var(--nv-text-muted);
  font-size:14px; line-height:1; background:none; border:none;
}
.nv-close:hover{ color:var(--nv-text-primary); }
.nv-state-panel{
  position:absolute; top:14px; left:14px; z-index:6; width:230px;
  background:var(--nv-bg-panel); backdrop-filter:blur(8px); border:1px solid var(--nv-border-soft);
  border-radius:14px; padding:14px 16px; box-shadow:0 14px 34px -10px #000d;
}
.nv-backbtn{
  display:flex; align-items:center; gap:6px; background:none; border:none; color:var(--nv-accent);
  font-family:'JetBrains Mono',monospace; font-size:11px; cursor:pointer; padding:0; margin-bottom:10px;
}
.nv-backbtn:hover{ text-decoration:underline; }
.nv-state-panel h3{ margin:0 0 2px; font-size:17px; font-weight:600; }
.nv-count{ font-size:11px; color:var(--nv-text-muted); margin-bottom:10px; }
.nv-city-block{ margin-bottom:10px; padding-top:8px; border-top:1px solid var(--nv-border-soft); }
.nv-city-block:first-of-type{ border-top:none; padding-top:0; }
.nv-cname{
  font-size:12px; color:var(--nv-accent2); font-weight:600; margin-bottom:4px;
  font-family:'JetBrains Mono',monospace;
}
.nv-empty{ font-size:12px; color:var(--nv-text-muted); font-style:italic; }
@media (max-width:640px){
  .nv-card{ width:170px; }
  .nv-state-panel{ width:190px; }
}
`;
